use std::io::{Read,Write};use spore_core::{cell_fresh_sweep_registration_v1::{Endpoint,Slot},cell_sweep_sorted_update_v1::update};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut input=Vec::new();std::io::stdin().read_to_end(&mut input)?;if input.len()!=128{return Err("expected four cases".into())}let mut out=Vec::new();for row in input.chunks_exact(32){let w=|i:usize|u32::from_le_bytes(row[i*4..i*4+4].try_into().unwrap());let mut endpoints=vec![Endpoint{opening:0,slot:0,value_bits:w(0)},Endpoint{opening:1,slot:0,value_bits:w(1)},Endpoint{opening:0,slot:1,value_bits:w(2)},Endpoint{opening:1,slot:1,value_bits:w(3)}];endpoints.sort_by(|a,b|f32::from_bits(a.value_bits).partial_cmp(&f32::from_bits(b.value_bits)).unwrap());let mut slots=vec![Slot{actor:0x10001,tag:0,endpoint_links:[0;4]},Slot{actor:0x20002,tag:0,endpoint_links:[0;4]}];for (i,e) in endpoints.iter().enumerate(){for axis in 0..2{slots[e.slot as usize].endpoint_links[axis+if e.opening==0{0}else{2}]=i as u16}}let r=update(&slots,&[endpoints.clone(),endpoints],0,[w(4),w(5)],[w(6),w(7)]).map_err(|e|format!("{e:?}"))?;for s in r.slots{out.extend(s.actor.to_le_bytes());out.extend(s.tag.to_le_bytes());for v in s.endpoint_links{out.extend(v.to_le_bytes())}}for a in r.axes{for e in a{out.extend(e.opening.to_le_bytes());out.extend(e.slot.to_le_bytes());out.extend(e.value_bits.to_le_bytes())}}out.extend([0xcc;16]);out.extend(2u32.to_le_bytes());}std::io::stdout().write_all(&out)?;Ok(())}
